let currentLanguage = DEFAULT_LANGUAGE;

export function normalizeLanguage(value) {
  return value === 'zh' ? 'zh' : DEFAULT_LANGUAGE;
}
export function setLanguage(value) {
  currentLanguage = normalizeLanguage(value);
  return currentLanguage;
}
export function getLanguage() {
  return currentLanguage;
}

// t('key', { name: value }) -> text in the current (or given) language. {name} placeholders are replaced with
// String(value) only when params has that own property; unknown keys return the key itself (visible, never thrown).
export function t(key, params, language = currentLanguage) {
  if (typeof key !== 'string' || !Object.hasOwn(I18N_MAP, key)) return String(key);
  const entry = I18N_MAP[key];
  const template = entry[normalizeLanguage(language)];
  if (params === undefined || params === null || typeof params !== 'object') return template;
  return template.replace(/\{([A-Za-z0-9_]+)\}/gu, (whole, name) => (Object.hasOwn(params, name) ? String(params[name]) : whole));
}

// A fixed-language translator (used by tests and exposed to the classic inline script as globalThis.HomeMcpI18n).
export function createTranslator(language = DEFAULT_LANGUAGE) {
  const lang = normalizeLanguage(language);
  return Object.freeze({ lang, locale: t('locale', undefined, lang), t: (key, params) => t(key, params, lang) });
}

// Fills [data-i18n] (textContent), [data-i18n-aria-label] (aria-label) and [data-i18n-placeholder] (placeholder) from the table. Text only.
export function applyDocumentText(doc, language = currentLanguage) {
  const lang = normalizeLanguage(language);
  doc.documentElement?.setAttribute?.('lang', t('html.lang', undefined, lang));
  for (const node of doc.querySelectorAll('[data-i18n]')) node.textContent = t(node.getAttribute('data-i18n'), undefined, lang);
  for (const node of doc.querySelectorAll('[data-i18n-aria-label]')) node.setAttribute('aria-label', t(node.getAttribute('data-i18n-aria-label'), undefined, lang));
  for (const node of doc.querySelectorAll('[data-i18n-placeholder]')) node.setAttribute('placeholder', t(node.getAttribute('data-i18n-placeholder'), undefined, lang));
  const toggle = doc.getElementById?.('lang-toggle');
  if (toggle) toggle.setAttribute('href', lang === 'zh' ? '?lang=en' : '?lang=zh');
}

if (typeof document !== 'undefined' && typeof location !== 'undefined') {
  let requested = null;
  try { requested = new URLSearchParams(location.search).get('lang'); } catch { requested = null; }
  setLanguage(requested);
  globalThis.HomeMcpI18n = createTranslator(currentLanguage);
  applyDocumentText(document, currentLanguage);
  globalThis.dispatchEvent?.(new Event('home-mcp-i18n-ready'));
}
